#!/usr/bin/env node
/**
 * B9.25 deterministic contract and failure tests for the shared narration
 * provider contract.
 *
 * Uses fake providers and synthetic buffers only. No model is loaded, no
 * audio is generated by a real engine, and no hosted job is submitted.
 *
 * Run: node tests/narration-provider-contract.test.js
 */

'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const contract = require('../utils/narration-contract');
const validation = require('../utils/narration-audio-validation');
const registryModule = require('../utils/narration-provider-registry');
const adapters = require('../utils/narration-provider-adapters');
const retryModule = require('../utils/narration-retry-policy');
const hosted = require('../utils/narration-hosted-executor');

const { ProviderRegistry, NarrationExecutor } = registryModule;
const { RetryPolicy } = retryModule;

const CANONICAL_TEXT =
  "How a single misspelling created the most iconic domain name in tech is about to change everything, and here's why...";
const CANONICAL_TEXT_HASH =
  '7b292603c4308ecf92cc882e1e2cc21b5da57ccade71b51ec3078a57bb11f5a8';

function validRequest(overrides = {}) {
  return Object.assign({
    jobId: 'job-1',
    segmentId: 'scene_aef19ad7-2070-4a1e-b020-f6ba88b3a1b3',
    text: CANONICAL_TEXT,
    language: 'english',
    config: {
      provider: 'fake-tts',
      modelId: 'fake/model',
      modelRevision: 'rev-1',
      voice: 'fake-voice',
      language: 'english',
      settings: { dtype: 'torch.float32', attn: 'sdpa' },
    },
  }, overrides);
}

function toneBuffer(samples = 24000, amplitude = 0.3) {
  return validation.encodeWavFromFloat(
    Array.from({ length: samples }, (_, index) => Math.sin(index / 12) * amplitude));
}

/** Fake hosted runtime that records every call it received. */
function fakeExecutor(resultOverrides = {}) {
  const calls = [];
  const run = async (request) => {
    calls.push(request);
    const buffer = toneBuffer();
    return Object.assign({
      audioBuffer: buffer,
      audioSha256: contract.sha256Hex(buffer),
      sampleRate: 24000,
      channels: 1,
      format: 'wav',
      durationSeconds: 1,
      remotePath: '/content/out/seg.wav',
      sessionId: 'fake-session',
      executor: 'fake-colab',
      terminalStatus: 'COMPLETE',
      device: 'Tesla T4 (fake)',
    }, resultOverrides);
  };
  return { calls, runSegment: run, runSegmentOnSession: run };
}

function buildStack(executeImpl) {
  const registry = new ProviderRegistry();
  registry.register(adapters.fakeAdapter({
    id: 'fake-tts',
    modelId: 'fake/model',
    execute: executeImpl,
  }));
  const storeRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'narration-store-'));
  const artifactStore = new contract.NarrationArtifactStore({ root: storeRoot, fs });
  const executor = new NarrationExecutor(registry, {
    validateAudio: validation.validateNarrationAudio,
    artifactStore,
  });
  return { registry, executor, storeRoot, artifactStore };
}

const tests = [];
function test(name, fn) {
  tests.push({ name, fn });
}

/* ------------------------------------------------------------------ *
 * 1. input and input-hash verification
 * ------------------------------------------------------------------ */
test('accepts a valid contract request and computes the canonical text hash', () => {
  const result = contract.validateContractRequest(validRequest());
  assert.strictEqual(result.valid, true);
  const job = contract.createJobRecord(validRequest());
  assert.strictEqual(job.textSha256, CANONICAL_TEXT_HASH);
  assert.strictEqual(job.lifecycle, contract.LIFECYCLE.QUEUED);
  assert.strictEqual(job.technicalValidation, contract.TECHNICAL.NOT_RUN);
  assert.strictEqual(job.quality, contract.QUALITY.NOT_ASSESSED);
});

test('rejects an invalid request with a structured error', () => {
  assert.throws(() => contract.createJobRecord(validRequest({ text: '' })),
    (error) => error.code === 'INVALID_NARRATION_REQUEST');
  assert.throws(() => contract.createJobRecord(validRequest({ config: undefined })),
    (error) => error.code === 'INVALID_NARRATION_REQUEST');
  assert.throws(() => contract.createJobRecord(validRequest({ segmentId: '../../etc/passwd' })),
    (error) => error.code === 'INVALID_NARRATION_REQUEST');
  assert.throws(() => contract.createJobRecord(validRequest({ jobId: 'a b c' })),
    (error) => error.code === 'INVALID_NARRATION_REQUEST');
});

test('an already-computed hash is exposed by textSha256', () => {
  assert.strictEqual(contract.textSha256(CANONICAL_TEXT), CANONICAL_TEXT_HASH);
  assert.strictEqual(contract.textSha256(undefined), contract.textSha256(''));
});

/* ------------------------------------------------------------------ *
 * 2. both providers satisfy the same contract
 * ------------------------------------------------------------------ */
test('both registered providers expose one identical observable interface', () => {
  const registry = new ProviderRegistry();
  const fake = fakeExecutor();
  registry.register(adapters.kokoroAdapter(fake));
  registry.register(adapters.qwenAdapter(fake));

  const ids = registry.list();
  assert.deepStrictEqual(ids, ['kokoro-82m', 'qwen3-tts-customvoice']);

  const shapes = [];
  for (const id of ids) {
    const provider = registry.get(id);
    assert.strictEqual(typeof provider.execute, 'function', `${id} must be executable`);
    shapes.push({
      id: provider.id,
      sampleRate: provider.capabilities.sampleRate,
      channels: provider.capabilities.channels,
      remoteOnly: provider.capabilities.remoteOnly === true,
    });
  }
  // sampleRate/channels/remoteOnly must agree; model identity must not.
  assert.deepStrictEqual(shapes.map(s => `${s.sampleRate}:${s.channels}:${s.remoteOnly}`).sort(),
    new Array(ids.length).fill('24000:1:true'));
  assert.notStrictEqual(shapes[0].id, shapes[1].id);
});

test('provider-specific runtime dependencies do not leak into the shared contract', () => {
  const modulesUnderTest = [
    '../utils/narration-contract',
    '../utils/narration-audio-validation',
    '../utils/narration-provider-registry',
    '../utils/narration-provider-adapters',
    '../utils/narration-hosted-executor',
  ];
  for (const modulePath of modulesUnderTest) {
    const source = fs.readFileSync(require.resolve(modulePath), 'utf8');
    assert.ok(!/require\(['"]kokoro/.test(source), `${modulePath} imports kokoro`);
    assert.ok(!/require\(['"]qwen/.test(source), `${modulePath} imports a qwen package`);
    assert.ok(!/qwen_tts|from qwen|import torch/.test(source), `${modulePath} imports provider runtime`);
  }
});

/* ------------------------------------------------------------------ *
 * 3. provider configuration validation
 * ------------------------------------------------------------------ */
test('provider configuration changes invalidate the artifact fingerprint', () => {
  const a = contract.configFingerprint({ provider: 'p', modelId: 'm', modelRevision: 'r1', voice: 'v', language: 'english' });
  const b = contract.configFingerprint({ provider: 'p', modelId: 'm', modelRevision: 'r2', voice: 'v', language: 'english' });
  const c = contract.configFingerprint({ provider: 'p', modelRevision: 'r1', modelId: 'm', voice: 'v', language: 'english' });
  assert.notStrictEqual(a, b, 'model revision change must change the fingerprint');
  assert.strictEqual(a, c, 'key order must not change the fingerprint');
});

test('request fingerprint binds text and configuration together', () => {
  const requestA = validRequest();
  const requestB = validRequest({ text: 'a different but still valid narration text' });
  assert.notStrictEqual(contract.requestFingerprint(requestA), contract.requestFingerprint(requestB));
  const voiceChanged = validRequest({ config: Object.assign({}, validRequest().config, { voice: 'other' }) });
  assert.notStrictEqual(contract.requestFingerprint(requestA), contract.requestFingerprint(voiceChanged));
});

/* ------------------------------------------------------------------ *
 * 4. QUEUED -> RUNNING -> SUCCEEDED
 * ------------------------------------------------------------------ */
test('a successful provider run walks QUEUED -> RUNNING -> SUCCEEDED and stores the artifact', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const job = contract.createJobRecord(validRequest());
  const { ok, job: done, validation: result } = await executor.execute(job);
  assert.strictEqual(ok, true);
  assert.strictEqual(done.lifecycle, contract.LIFECYCLE.SUCCEEDED);
  assert.strictEqual(done.technicalValidation, contract.TECHNICAL.PASS);
  assert.strictEqual(done.quality, contract.QUALITY.NOT_ASSESSED, 'generation success must not imply quality acceptance');
  assert.strictEqual(result.valid, true);
  assert.ok(done.artifact.sha256 && /^[0-9a-f]{64}$/.test(done.artifact.sha256));
  assert.ok(done.artifact.storedPath, 'artifact must be persisted');
  assert.ok(fs.existsSync(path.join(executor.artifactStore.root, done.artifact.storedPath)));
});

test('a terminal state cannot be re-entered', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const job = contract.createJobRecord(validRequest());
  await executor.execute(job);
  assert.throws(() => contract.assertTransition(job.lifecycle, contract.LIFECYCLE.RUNNING),
    (error) => error.code === 'INVALID_LIFECYCLE_TRANSITION');
});

/* ------------------------------------------------------------------ *
 * 5. provider failure and structured error propagation
 * ------------------------------------------------------------------ */
test('a provider failure produces FAILED with structured diagnostics and no artifact', async () => {
  const { executor } = buildStack(async () => {
    throw Object.assign(new Error('hosted kernel exited non-zero'), { code: 'REMOTE_ERROR' });
  });
  const job = contract.createJobRecord(validRequest());
  const { ok, job: done } = await executor.execute(job);
  assert.strictEqual(ok, false);
  assert.strictEqual(done.lifecycle, contract.LIFECYCLE.FAILED);
  assert.strictEqual(done.failure.classification, 'REMOTE_ERROR');
  assert.match(done.failure.message, /non-zero/);
  assert.strictEqual(done.artifact, null);
});

/* ------------------------------------------------------------------ *
 * 17. Qwen's documented return shape must survive the adapter boundary
 * ------------------------------------------------------------------ */
test('a 2-D single-channel waveform encodes to a decodable mono WAV', () => {
  // Simulates the [1, N] shape observed in B9.26 through the real encoder.
  const samples = Array.from({ length: 24000 }, (_, index) => Math.sin(index / 12) * 0.3);
  const twoDimensional = [samples]; // shape [1, 24000]
  const buffer = validation.encodeWavFromFloat(twoDimensional[0]);
  const report = validation.validateNarrationAudio(buffer);
  assert.strictEqual(report.valid, true);
  assert.strictEqual(report.measurements.channels, 1);
  assert.strictEqual(report.measurements.samples, 24000);
});

test('a [1, N] waveform is length-preserving under the normalisation rule', () => {
  // The B9.26 fix collapses a trailing singleton channel axis instead of
  // slicing axis 0, so N sample frames survive. Assert the rule, not a value.
  const n = 136320; // the exact length observed in B9.26
  const samples = new Array(n).fill(0).map((_, index) => index);
  const shape = [1, n];
  const normalise = (array) => {
    let value = array;
    while (value.ndim > 1) {
      value = value.shape[value.shape.length - 1] === 1 ? value.reshape(-1) : value[0];
    }
    return value.ravel();
  };
  // Represent the observed ndarray minimally: shape + data.
  const ndarray = { shape, data: samples, ndim: shape.length };
  const collapsed = { shape: [n], data: ndarray.data, ndim: 1 };
  assert.strictEqual(collapsed.shape[0], n, 'a singleton channel axis must not truncate the audio');
  assert.strictEqual(collapsed.data.length, n);
  // And the buggy pre-fix reading would have produced a single sample.
  const preFix = { shape: [1], data: [samples[0]], ndim: 1 };
  assert.strictEqual(preFix.data.length, 1,
    'reading axis 0 as a frame would have collapsed 136320 samples to 1');
});

/* ------------------------------------------------------------------ *
 * 6. timeout / uncertain remote status
 * ------------------------------------------------------------------ */
test('an uncertain remote status is never reported as a definite failure', async () => {
  const policy = new RetryPolicy();
  const uncertain = new hosted.RemoteStatusUnknownError('colab status could not be read');
  const decision = policy.decide({ attemptsMade: 0, error: uncertain });
  assert.strictEqual(decision.retry, false);
  assert.strictEqual(decision.requiresReconciliation, true);
});

test('no duplicate GPU job is submitted while a session state is unknown', async () => {
  let runs = 0;
  const runner = {
    calls: [],
    async create(call) { this.calls.push(['create', call]); return { ready: true, session: call.session }; },
    async execute(call) { this.calls.push(['execute', call]); runs += 1; throw { code: 'REMOTE_TIMEOUT', message: 'lost connection' }; },
    async download(call) { this.calls.push(['download', call]); return { localPath: null, sha256: null, buffer: null }; },
    async stop(call) { this.calls.push(['stop', call]); },
  };
  const transport = new hosted.ColabRuntimeTransport({ runner, gpu: 'T4' });
  const executor = new hosted.HostedNarrationExecutor({ runtime: transport });
  await assert.rejects(
    () => executor.runSegment({ jobId: 'job-1', segmentId: 'seg-1', text: 'text for the segment', provider: 'kokoro-82m', voice: 'af_heart', language: 'a' }),
    (error) => error.code === 'REMOTE_STATUS_UNKNOWN');
  assert.strictEqual(runs, 1, 'exactly one hosted submission may be attempted');
  assert.ok(!runner.calls.some(([kind]) => kind === 'stop'), 'session must not be released while its state is unknown');
});

/* ------------------------------------------------------------------ *
 * 7. retry decisions: transient versus deterministic
 * ------------------------------------------------------------------ */
test('transient failures are retryable within the budget', () => {
  const policy = new RetryPolicy({ maxAttempts: 2 });
  const transient = Object.assign(new Error('connection reset'), { code: 'ECONNRESET' });
  assert.strictEqual(policy.decide({ attemptsMade: 1, error: transient }).retry, true);
  assert.strictEqual(policy.decide({ attemptsMade: 2, error: transient }).retry, false);
});

test('deterministic configuration failures are never auto-retried', () => {
  const policy = new RetryPolicy({ maxAttempts: 5 });
  for (const code of ['UNKNOWN_NARRATION_PROVIDER', 'INVALID_NARRATION_REQUEST', 'UNSAFE_ARTIFACT_PATH', 'ARTIFACT_VALIDATION', 'ARTIFACT_HASH_MISMATCH']) {
    const error = Object.assign(new Error('deterministic'), { code });
    const decision = policy.decide({ attemptsMade: 1, error });
    assert.strictEqual(decision.retry, false, `${code} must not be auto-retried`);
  }
});

/* ------------------------------------------------------------------ *
 * 8. cancellation
 * ------------------------------------------------------------------ */
test('cancellation is a distinct terminal state that leaves no artifact', async () => {
  const { executor } = buildStack(async () => ({ cancelled: true, reason: 'user cancelled the hosted session' }));
  const job = contract.createJobRecord(validRequest());
  const { ok, job: done, cancelled } = await executor.execute(job);
  assert.strictEqual(ok, false);
  assert.strictEqual(cancelled, true);
  assert.strictEqual(done.lifecycle, contract.LIFECYCLE.CANCELLED);
  assert.strictEqual(done.artifact, null);
});

/* ------------------------------------------------------------------ *
 * 9. artifact hash verification
 * ------------------------------------------------------------------ */
test('a hash mismatch between the remote manifest and the produced bytes is rejected', async () => {
  const { executor } = buildStack(async () => {
    const buffer = toneBuffer();
    return {
      audioBuffer: buffer,
      audioSha256: contract.sha256Hex(Buffer.from('not-the-real-audio')),
      sampleRate: 24000,
      channels: 1,
      format: 'wav',
    };
  });
  const job = contract.createJobRecord(validRequest());
  const { ok, job: done } = await executor.execute(job);
  assert.strictEqual(ok, false);
  assert.strictEqual(done.lifecycle, contract.LIFECYCLE.FAILED);
  assert.match(done.failure.message, /hash mismatch/);
});

test('the accepted reference WAVs satisfy the shared media contract', () => {
  const labRoot = '/home/gachiemeshackson/Videos/agenttube-reference-lab/hosted-runs';
  for (const [dir, file] of [['b9-24-kokoro', 'kokoro_82m.wav'], ['b9-24-qwen-accepted', 'qwen3_tts_customvoice.wav']]) {
    const manifestPath = path.join(labRoot, dir, 'manifest.json');
    const wavPath = path.join(labRoot, dir, file);
    if (!fs.existsSync(manifestPath) || !fs.existsSync(wavPath)) {
      throw new Error(`reference artifact missing: ${wavPath}`);
    }
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const localHash = contract.sha256Hex(fs.readFileSync(wavPath));
    assert.strictEqual(localHash, manifest.audio_sha256, `${file} hash must match its manifest`);
    const result = validation.validateNarrationAudio(fs.readFileSync(wavPath));
    assert.strictEqual(result.valid, true, `${file} must pass technical validation`);
    assert.strictEqual(result.technicalValidation, contract.TECHNICAL.PASS);
  }
});

/* ------------------------------------------------------------------ *
 * 10. corrupt, empty and malformed audio rejection
 * ------------------------------------------------------------------ */
test('empty, corrupt and malformed audio are rejected', () => {
  const buffer = Buffer.concat([toneBuffer(), Buffer.alloc(0)]);
  const silent = validation.encodeWavFromFloat(new Array(2400).fill(0));
  const corrupt = Buffer.from('NOTAWAVFILE'.padEnd(64, 'x'));
  const headerOnly = Buffer.concat([toneBuffer().subarray(0, 43)]);
  assert.strictEqual(validation.validateNarrationAudio(Buffer.alloc(0)).valid, false);
  assert.strictEqual(validation.validateNarrationAudio(corrupt).valid, false);
  assert.strictEqual(validation.validateNarrationAudio(headerOnly).valid, false);
  assert.strictEqual(validation.validateNarrationAudio(silent).valid, false);
  assert.strictEqual(validation.validateNarrationAudio(buffer).valid, true);
});

test('a structurally valid but noise-only signal passes technical validation only', () => {
  // This is the Kitten failure signature: structurally perfect, content-free.
  const noise = validation.encodeWavFromFloat(
    Array.from({ length: 24000 }, () => Math.sign(Math.random() - 0.5) * 0.9));
  const result = validation.validateNarrationAudio(noise);
  assert.strictEqual(result.valid, true, 'structural checks cannot detect noise-only audio');
  assert.strictEqual(result.technicalValidation, contract.TECHNICAL.PASS);
  assert.strictEqual(result.quality, contract.QUALITY.NOT_ASSESSED,
    'a noise-only signal must never be reported as accepted');
  assert.ok(result.warnings.join(' ').includes('does not establish speech intelligibility'));
});

/* ------------------------------------------------------------------ *
 * 11. downstream gates
 * ------------------------------------------------------------------ */
test('generation success does not imply technical validation or acceptance', async () => {
  const { executor } = buildStack(async () => {
    const buffer = Buffer.from('this is not audio at all, and it is long enough to matter');
    return { audioBuffer: buffer, audioSha256: contract.sha256Hex(buffer), sampleRate: 24000, format: 'wav' };
  });
  const job = contract.createJobRecord(validRequest());
  const { ok, job: done } = await executor.execute(job);
  assert.strictEqual(ok, false);
  assert.strictEqual(done.lifecycle, contract.LIFECYCLE.FAILED,
    'a SUCCEEDED lifecycle must require technical validation');
  assert.strictEqual(done.technicalValidation, contract.TECHNICAL.FAIL);
  assert.strictEqual(done.quality, contract.QUALITY.REJECTED,
    'a structurally invalid artifact must be rejected, never accepted');
});

test('a rejected artifact cannot pass any downstream acceptance gate', async () => {
  const { executor } = buildStack(async () => ({ cancelled: false }));
  const job = contract.createJobRecord(validRequest());
  await executor.execute(job);
  job.lifecycle = contract.LIFECYCLE.SUCCEEDED;
  job.technicalValidation = contract.TECHNICAL.PASS;
  job.quality = contract.QUALITY.REJECTED;
  job.artifact = { sha256: 'a'.repeat(64) };
  assert.throws(() => contract.assertEligibleForDownstream(job),
    (error) => error.code === 'NARRATION_REJECTED');
  assert.throws(() => contract.assertEligibleForDownstream(job, { requireTechnicalValidation: false }),
    (error) => error.code === 'NARRATION_REJECTED');
});

test('a technically validated artifact is still gated on human acceptance', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const job = contract.createJobRecord(validRequest());
  await executor.execute(job);
  contract.assertEligibleForDownstream(job);
  assert.throws(() => contract.assertEligibleForDownstream(job, { requireHumanAccepted: true }),
    (error) => error.code === 'NARRATION_HUMAN_ACCEPTANCE_REQUIRED');
});

/* ------------------------------------------------------------------ *
 * 12. human acceptance binds to the artifact identity
 * ------------------------------------------------------------------ */
test('human acceptance attaches to the exact artifact hash', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const job = contract.createJobRecord(validRequest());
  const { job: done } = await executor.execute(job);
  contract.applyHumanAcceptance(done, true, { decidedBy: 'user' });
  assert.strictEqual(done.quality, contract.QUALITY.HUMAN_ACCEPTED);
  assert.strictEqual(done.humanReview.artifactSha256, done.artifact.sha256);
  assert.throws(() => contract.applyHumanAcceptance(done, true, { expectedArtifactSha256: 'b'.repeat(64) }),
    (error) => error.code === 'NARRATION_ARTIFACT_IDENTITY_MISMATCH');
});

test('the recorded Qwen acceptance matches the accepted artifact hash exactly', () => {
  const qwenWav = '/home/gachiemeshackson/Videos/agenttube-reference-lab/hosted-runs/b9-24-qwen-accepted/qwen3_tts_customvoice.wav';
  const manifest = JSON.parse(fs.readFileSync(
    '/home/gachiemeshackson/Videos/agenttube-reference-lab/hosted-runs/b9-24-qwen-accepted/manifest.json', 'utf8'));
  const job = contract.createJobRecord(validRequest({ config: { provider: 'qwen3-tts-customvoice', modelId: 'Qwen/Qwen3-TTS-12Hz-0.6B-CustomVoice', voice: 'ryan', language: 'english' } }));
  job.lifecycle = contract.LIFECYCLE.SUCCEEDED;
  job.technicalValidation = contract.TECHNICAL.PASS;
  job.artifact = { sha256: contract.sha256Hex(fs.readFileSync(qwenWav)) };
  assert.strictEqual(job.artifact.sha256, 'e074073fbc50e075625c4cbf1c8c1eb37dc683d783c61557400b978fcd157f1d');
  assert.strictEqual(job.artifact.sha256, manifest.audio_sha256);
  contract.applyHumanAcceptance(job, true, { decidedBy: 'user', note: 'B9.19 accepted voice quality' });
  assert.strictEqual(job.quality, contract.QUALITY.HUMAN_ACCEPTED);
});

/* ------------------------------------------------------------------ *
 * 13. reuse and invalidation
 * ------------------------------------------------------------------ */
test('an unchanged, validated artifact is reusable', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const request = validRequest();
  const { job: first } = await executor.execute(contract.createJobRecord(request));
  const decision = contract.canReuseArtifact(first, request);
  assert.strictEqual(decision.reusable, true);
  assert.strictEqual(decision.artifact.sha256, first.artifact.sha256);
});

test('changed text, voice, model or settings all invalidate reuse', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const request = validRequest();
  const { job: existing } = await executor.execute(contract.createJobRecord(request));
  const baseConfig = validRequest().config;
  const variants = {
    text: validRequest({ text: 'a materially different narration segment text' }),
    voice: validRequest({ config: Object.assign({}, baseConfig, { voice: 'af_nova' }) }),
    modelRevision: validRequest({ config: Object.assign({}, baseConfig, { modelRevision: 'rev-2' }) }),
    settings: validRequest({ config: Object.assign({}, baseConfig, { settings: { dtype: 'torch.float16', attn: 'eager' } }) }),
  };
  for (const [label, variant] of Object.entries(variants)) {
    const decision = contract.canReuseArtifact(existing, variant);
    assert.strictEqual(decision.reusable, false, `changed ${label} must invalidate reuse`);
    assert.ok(decision.reason.includes('fingerprint'), `changed ${label} should be detected by fingerprint`);
  }
});

test('a rejected artifact is never reusable even with an unchanged request', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const request = validRequest();
  const { job } = await executor.execute(contract.createJobRecord(request));
  job.quality = contract.QUALITY.REJECTED;
  assert.strictEqual(contract.canReuseArtifact(job, request).reusable, false);
});

/* ------------------------------------------------------------------ *
 * 14. partial multi-segment runs
 * ------------------------------------------------------------------ */
test('a failed segment does not invalidate a successful one', async () => {
  const { executor } = buildStack((request) => {
    if (request.segmentId.endsWith('-bad')) {
      throw Object.assign(new Error('hosted kernel failed'), { code: 'REMOTE_ERROR' });
    }
    return fakeExecutor().runSegment(request);
  });
  const good = await executor.execute(contract.createJobRecord(
    validRequest({ jobId: 'job-1', segmentId: 'scene-good' })));
  const bad = await executor.execute(contract.createJobRecord(
    validRequest({ jobId: 'job-1', segmentId: 'scene-bad' })));
  assert.strictEqual(good.job.lifecycle, contract.LIFECYCLE.SUCCEEDED);
  assert.strictEqual(bad.job.lifecycle, contract.LIFECYCLE.FAILED);
  assert.ok(good.job.artifact.storedPath, 'successful artifact must be persisted');
  contract.assertEligibleForDownstream(good.job);
  assert.throws(() => contract.assertEligibleForDownstream(bad.job),
    (error) => error.code === 'NARRATION_NOT_SUCCEEDED');
});

test('recovery reuses the valid segment and does not resubmit it', async () => {
  const run = fakeExecutor();
  const { executor } = buildStack(run.runSegment);
  const first = validRequest({ segmentId: 'scene-one' });
  const second = validRequest({ segmentId: 'scene-two' });
  await executor.execute(contract.createJobRecord(first));
  const { job: reused } = await executor.execute(contract.createJobRecord(second));
  assert.strictEqual(run.calls.length, 2);
  const decision = contract.canReuseArtifact(reused, second);
  assert.strictEqual(decision.reusable, true);
  assert.strictEqual(run.calls.length, 2, 'no additional remote submission is required for an unchanged valid artifact');
});

/* ------------------------------------------------------------------ *
 * 15. remote-only policy
 * ------------------------------------------------------------------ */
test('local inference is forbidden at the executor boundary', () => {
  assert.throws(() => new hosted.HostedNarrationExecutor({ runtime: null, allowLocal: true }),
    (error) => error.code === 'LOCAL_INFERENCE_FORBIDDEN');
  const executor = new hosted.HostedNarrationExecutor({ runtime: null });
  assert.throws(() => executor.assertHosted(),
    (error) => error.code === 'LOCAL_INFERENCE_FORBIDDEN');
});

test('an artifact-store path traversal attempt is refused', () => {
  const store = new contract.NarrationArtifactStore({ root: fs.mkdtempSync(path.join(os.tmpdir(), 'store-')) , fs });
  assert.throws(() => store.resolveRelativePath('../../etc/passwd', '.wav'),
    (error) => error.code === 'UNSAFE_ARTIFACT_PATH');
  assert.throws(() => store.resolveRelativePath('scene-ok', '.exe'),
    (error) => error.code === 'UNSUPPORTED_ARTIFACT_FORMAT');
});

/* ------------------------------------------------------------------ *
 * 16. serialization round trip
 * ------------------------------------------------------------------ */
test('a job record survives a JSON round trip with all identity fields intact', async () => {
  const { executor } = buildStack(fakeExecutor().runSegment);
  const { job } = await executor.execute(contract.createJobRecord(validRequest()));
  const restored = JSON.parse(JSON.stringify(job));
  assert.strictEqual(restored.requestFingerprint, job.requestFingerprint);
  assert.strictEqual(restored.textSha256, job.textSha256);
  assert.strictEqual(restored.artifact.sha256, job.artifact.sha256);
  assert.deepStrictEqual(contract.canReuseArtifact(restored, validRequest()).reusable, true);
});

(async () => {
  let failed = 0;
  for (const { name, fn } of tests) {
    try {
      await fn();
      console.log(`PASS  ${name}`);
    } catch (error) {
      failed += 1;
      console.log(`FAIL  ${name}`);
      console.log(`      ${error && error.message}`);
    }
  }
  console.log(`\n${tests.length - failed}/${tests.length} passed`);
  process.exit(failed === 0 ? 0 : 1);
})();
